import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"直方图与基数","description":"","frontmatter":{"title":"直方图与基数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/histogram-card.md","filePath":"cs/histogram-card.md","lastUpdated":1789023840000}'),h={name:"cs/histogram-card.md"};function p(m,a,_,B,A,u){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="直方图与基数" tabindex="-1">直方图与基数 <a class="header-anchor" href="#直方图与基数" aria-label="Permalink to &quot;直方图与基数&quot;">​</a></h1><div class="epigraph"><p>选择率不能靠「均匀且独立」蒙对；直方图把列上的值分布收成可查的桶，基数估计才有输入。</p><footer>—— 据 Selinger et al., 1979；Ioannidis 对直方图；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/cost-estimate">上一课</a>给出页 I/O 与 CPU 的代价模型。本课不重写公式结构。缺口是模型里的数字：谓词选择率、连接结果有多大。目录若只存 <code>COUNT(*)</code> 与 min/max，倾斜数据会让嵌套循环看起来便宜。直方图与频次计数是统计合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代价估计留下「用目录里的基数」。均匀假设：<code>col = c</code> 的选择率 = 1/NDV。现实是长尾。等宽/等高直方图、最频繁值列表，把分布收成粗图。多列相关破坏独立假设，联合选择率估爆——本课承认缺口，不把多维直方图当必装。</p><p><span class="marginnote">过期统计比错误公式更常见：插入大量新键后仍用旧 NDV。ANALYZE 一类命令是维护，不是优化器搜索。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对单列：维护 NDV、NULL 比例、直方图桶。等值查频次或桶平均；范围用桶宽度积分。连接基数：用 NDV 公式当独立时的起点。估计进入<a href="/cs/query-plan">查询计划</a> 每个节点。本课不把采样估 NDV 的全部算法写完。</p>',8)),(e(),n(E,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E5%88%97%E4%B8%8A%E7%9A%84%E7%9C%9F%E5%AE%9E%E5%88%86%E5%B8%83%22%5D%20--%3E%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%20%2F%20%E9%AB%98%E9%A2%91%E5%80%BC%22%5D%0A%20%20HIST%20--%3E%20SEL%5B%22%E8%B0%93%E8%AF%8D%E9%80%89%E6%8B%A9%E7%8E%87%22%5D%0A%20%20SEL%20--%3E%20CARD%5B%22%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%E5%9F%BA%E6%95%B0%22%5D%0A%20%20CARD%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%E6%95%B0%E5%AD%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>基数是计划搜索的燃料：估小了会选 NLJ 打大表，估大了会多余排序。它不改变 SQL 语义，只改变物理树。改写课会先变形再估；统计错则漂亮的树仍慢。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入学习优化器当主干。逻辑树如何先变瘦，下一课查询改写。</p><p>后课默认：选择率来自统计，不是均匀口号。先改逻辑树再估。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>直方图把分布收成桶，供基数估计。</li><li>独立与均匀是默认谎言，倾斜时失败。</li><li>逻辑改写下一课。</li><li>出处：Selinger 1979；Ioannidis；Ramakrishnan and Gehrke。</li></ul>',7))])}const T=o(h,[["render",p]]);export{D as __pageData,T as default};
